import express, {
  type Application,
  type Request,
  type Response,
} from "express";
import { AuthRoutes } from "./app/module/auth/auth.route";
import { globalErrorHandler } from "./app/middleware/globalErrorHandler";
import { notFound } from "./app/middleware/notFound";
import httpStatus from "http-status";
import cors from "cors";
import config from "./app/config";
import cookieParser from "cookie-parser";
import { UserRoutes } from "./app/module/user/user.route";
import { ComplainRoutes } from "./app/module/complain/complain.route";
import { PaymentRoutes } from "./app/module/payment/payment.route";
import { AssignRoutes } from "./app/module/assign/assign.route";

const app: Application = express();

app.use(
  cors({
    origin: config.frontend_url,
    credentials: true,
  }),
);

// Middleware to parse JSON bodies
app.use(express.json());
app.use(cookieParser());

// Enable URL-encoded form data parsing
app.use(express.urlencoded({ extended: true }));

app.get("/", (req: Request, res: Response) => {
  res.send("Hello, World!");
});

app.use("/api/v1/auth", AuthRoutes);
app.use("/api/v1/users", UserRoutes);
app.use("/api/v1/complains", ComplainRoutes);
app.use("/api/v1/payments", PaymentRoutes);
app.use("/api/v1/assigns", AssignRoutes);

// Basic route
app.get("/", async (req: Request, res: Response) => {
  res.status(httpStatus.OK).json({
    success: true,
    message: "Welcome to City Complain & Service Platform",
  });
});

app.use(globalErrorHandler);
app.use(notFound);

export default app;
